import{c as d,ah as s,L as i,O as e,i as a,v as r}from"./chunks/framework.YKVbmyBD.js";const b=JSON.parse('{"title":"修改 PS1 环境变量自定义终端外观","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/configure-system/custom-terminal.md","filePath":"fovlin-notes/linux-guide/configure-system/custom-terminal.md"}'),h={name:"fovlin-notes/linux-guide/configure-system/custom-terminal.md"};function l(n,t,p,o,k,c){return s(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="修改-ps1-环境变量自定义终端外观" tabindex="-1">修改 PS1 环境变量自定义终端外观 <a class="header-anchor" href="#修改-ps1-环境变量自定义终端外观" aria-label="Permalink to “修改 PS1 环境变量自定义终端外观”">​</a></h1><p>Linux 系统中，可以通过修改 PS1 环境变量来修改 bash shell 提示符的样式。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>例如编辑 <code>.bashrc</code> 文件，一个示例环境变量如下，写入以下行来更改PS1环境变量。</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PS1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;\\[\\e[1;32m\\]\\u@\\h\\[\\e[0m\\]:\\[\\e[1;34m\\]\\w\\[\\e[0m\\]\\$ &#39;</span></span></code></pre></div><p>重启 bash shell，或者执行 <code>source .bashrc</code> 命令，即可生效。</p><p>此样式为默认的 Ubuntu 终端样式，你可以根据自己喜欢的样式进行修改。</p><p>下列是所有的变量代表的含义。</p><h2 id="各变量含义" tabindex="-1">各变量含义 <a class="header-anchor" href="#各变量含义" aria-label="Permalink to “各变量含义”">​</a></h2><p>显示设置：</p><table tabindex="0"><thead><tr><th>变量</th><th>描述</th></tr></thead><tbody><tr><td>\\a</td><td>响铃</td></tr><tr><td>\\d</td><td>显示当前日期</td></tr><tr><td>\\h</td><td>显示当前主机名</td></tr><tr><td>\\n</td><td>换行</td></tr><tr><td>\\s</td><td>显示当前 bash 的版本</td></tr><tr><td>\\t</td><td>显示当前时间</td></tr><tr><td>\\u</td><td>显示当前用户名</td></tr><tr><td>\\v</td><td>显示当前 bash 版本</td></tr><tr><td>\\w</td><td>显示当前工作目录</td></tr><tr><td>$</td><td>显示当前用户权限</td></tr></tbody></table><p>颜色设置:</p><p>使用 <code>\\[\\e[a;b;...;Xm\\]</code> 或 <code>\\[\\033[a;b;...;Xm\\]</code> 来设置后续字符的颜色，其中 a、b、... 表示附加效果，使用 <code>;</code> 隔开，可省略，X 为必须的主要效果，如仅设置字体颜色为绿色，使用 <code>\\[\\e[32m\\]</code>。</p><p>不同 X 值代表的字体效果如下：</p><table tabindex="0"><thead><tr><th>效果</th><th>描述</th></tr></thead><tbody><tr><td>0</td><td>重置效果</td></tr><tr><td>1</td><td>粗体</td></tr><tr><td>2</td><td>半透明</td></tr><tr><td>3</td><td>斜体</td></tr><tr><td>4</td><td>下划线</td></tr><tr><td>5</td><td>闪烁</td></tr><tr><td>7</td><td>反色</td></tr><tr><td>8</td><td>透明</td></tr><tr><td>9</td><td>删除线</td></tr><tr><td>30</td><td>黑色</td></tr><tr><td>31</td><td>红色</td></tr><tr><td>32</td><td>绿色</td></tr><tr><td>33</td><td>黄色</td></tr><tr><td>34</td><td>蓝色</td></tr><tr><td>35</td><td>紫色</td></tr><tr><td>36</td><td>青色</td></tr><tr><td>37</td><td>白色</td></tr><tr><td>40</td><td>黑色背景</td></tr><tr><td>41</td><td>红色背景</td></tr><tr><td>42</td><td>绿色背景</td></tr><tr><td>43</td><td>黄色背景</td></tr><tr><td>44</td><td>蓝色背景</td></tr><tr><td>45</td><td>紫色背景</td></tr><tr><td>46</td><td>青色背景</td></tr><tr><td>47</td><td>白色背景</td></tr></tbody></table><p>例如使用以下 PS1 环境变量：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PS1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;\\[\\e[1;32m\\]&lt;\\h&gt;\\[\\e[0m\\]-\\[\\e[1;32m\\]&lt;\\u&gt;\\[\\e[0m\\]-\\[\\e[1;34m\\]&lt;\\w&gt;\\[\\e[0m\\]\\n&gt; &#39;</span></span></code></pre></div><p>将得到以下效果： <img src="'+a+'" alt=""></p><p>或是得到 Kali 的终端效果：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PS1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[\\e[1;32m\\](\\u\\[\\e[1;33m\\]@\\h\\[\\e[1;32m\\])\\[\\e[0m\\]-\\[\\e[1;34m\\]&lt;\\w&gt;\\[\\e[0m\\]\\n└&lt;&#39;</span></span></code></pre></div><p>将得到以下效果： <img src="'+r+'" alt=""></p>',21)])])}const m=d(h,[["render",l]]);export{b as __pageData,m as default};
